SAAS,EAAE,kBAAkB,CAAC,OAAO,CAAC,YAAG,KAAK,GAAQ,EACrE,eAAe,IAAI,CAChB,eAAM,SAAS,EAAE,kBAAkB,CAAC,aAAa,CAAC,YAAG,WAAW,GAAQ,CAC3E,EACA,eAAe,IAAI,CAChB,eAAM,SAAS,EAAE,kBAAkB,CAAC,aAAa,CAAC,YAC7C,sBAAsB,GACpB,CACV,IACI,EACR,sBAAsB,EAAE,EACxB,eAAe,CAAC,EAAE,CAAC,EAEnB,YAAY,IAAI,CACb,KAAC,OAAO,IACJ,SAAS,EAAE,SAAS,KAAK,KAAK,CAAC,CAAC,CAAC,CAAC,MAAM,EAAE,QAAQ,CAAC,CAAC,CAAC,CAAC,CAAC,OAAO,EAAE,QAAQ,CAAC,EACzE,QAAQ,QACR,SAAS,EAAE,kBAAkB,CAAC,eAAe,CAAC,EAC9C,OAAO,EACH,KAAC,KAAK,IACF,SAAS,EAAE,kBAAkB,CAAC,uBAAuB,CAAC,EACtD,KAAK,EAAC,OAAO,EACb,OAAO,EAAE,cAAK,IAAI,EAAC,cAAc,YAAE,YAAY,GAAO,GACxD,YAGN,+BACgB,CAAC,CAAC,uBAAuB,CAAC,EACtC,IAAI,EAAE,QAAQ,EACd,SAAS,EAAE,kBAAkB,CAAC,YAAY,CAAC,YAE3C,KAAC,IAAI,IAAC,IAAI,EAAE,mBAAmB,EAAE,IAAI,EAAE,IAAI,KAAK,GAAG,CAAC,CAAC,CAAC,EAAE,CAAC,CAAC,CAAC,EAAE,GAAI,GAC5D,GACH,CACb,EAED,KAAC,IAAI,IACD,SAAS,EAAE,kBAAkB,CAAC,cAAc,EAAE,EAAC,QAAQ,EAAC,CAAC,EACzD,IAAI,EAAE,WAAW,iBACL,MAAM,GACpB,IACA,GACO,CACpB,CAAC;AACN,CAAC,CAAC,CAAC;AAEH,aAAa,CAAC,WAAW,GAAG,eAAe,CAAC","sourcesContent":["'use client';

import * as React from 'react';

import {ChevronDown, TriangleExclamation} from '@gravity-ui/icons';

import {Alert} from '../../../Alert';
import {Icon} from '../../../Icon';
import {Popover} from '../../../Popover';
import {useDirection} from '../../../theme';
import type {AriaLabelingProps} from '../../../types';
import type {CnMods} from '../../../utils/cn';
import {filterDOMProps} from '../../../utils/filterDOMProps';
import {selectControlBlock, selectControlButtonBlock} from '../../constants';
import i18n from '../../i18n';
import type {
    SelectProps,
    SelectRenderClearArgs,
    SelectRenderControl,
    SelectRenderCounter,
    SelectRenderTriggerProps,
} from '../../types';
import {SelectClear} from '../SelectClear/SelectClear';
import {SelectCounter} from '../SelectCounter/SelectCounter';

import './SelectControl.scss';

type ControlProps = {
    toggleOpen: () => void;
    renderControl?: SelectRenderControl;
    renderCounter?: SelectRenderCounter;
    view: NonNullable<SelectProps['view']>;
    size: NonNullable<SelectProps['size']>;
    pin: NonNullable<SelectProps['pin']>;
    selectedOptionsContent: React.ReactNode;
    className?: string;
    qa?: string;
    label?: string;
    placeholder?: SelectProps['placeholder'];
    isErrorVisible?: boolean;
    errorMessage?: SelectProps['errorMessage'];
    disabled?: boolean;
    value: NonNullable<SelectProps['value']>;
    clearValue: () => void;
    hasClear?: boolean;
    hasCounter?: boolean;
    title?: string;
    onKeyDown?: (e: React.KeyboardEvent<HTMLElement>) => void;
    open: boolean;
    popupId: string;
    selectId: string;
    activeIndex?: number;
} & AriaLabelingProps;

export const SelectControl = React.forwardRef<HTMLButtonElement, ControlProps>((props, ref) => {
    const {
        toggleOpen,
        clearValue,
        onKeyDown,
        renderControl,
        view,
        size,
        pin,
        selectedOptionsContent,
        className,
        qa,
        label,
        placeholder,
        isErrorVisible,
        errorMessage,
        open,
        disabled,
        value,
        hasClear,
        popupId,
        selectId,
        activeIndex,
        renderCounter,
        hasCounter,
        title,
    } = props;
    const showOptionsText = Boolean(selectedOptionsContent);
    const showPlaceholder = Boolean(placeholder && !showOptionsText);
    const hasValue = Array.isArray(value) && value.filter(Boolean).length > 0;

    const direction = useDirection();

    const [isDisabledButtonAnimation, setIsDisabledButtonAnimation] = React.useState(false);

    const controlMods: CnMods = {
        open,
        size,
        pin,
        disabled,
        error: isErrorVisible,
        'has-clear': hasClear,
        'no-active': isDisabledButtonAnimation,
        'has-value': hasValue,
    };

    const buttonMods: CnMods = {
        open,
        size,
        view,
        pin,
        disabled,
        error: isErrorVisible,
    };

    const handleControlClick = React.useCallback(
        (e?: React.MouseEvent<HTMLElement>) => {
            // Fix for Safari
            // https://developer.mozilla.org/en-US/docs/Web/HTML/Element/button#clicking_and_focus
            if (e && e.currentTarget !== document.activeElement && 'focus' in e.currentTarget) {
                e.currentTarget.focus();
            }

            toggleOpen();
        },
        [toggleOpen],
    );

    const disableButtonAnimation = React.useCallback(() => {
        setIsDisabledButtonAnimation(true);
    }, []);
    const enableButtonAnimation = React.useCallback(() => {
        setIsDisabledButtonAnimation(false);
    }, []);
    const handleOnClearIconClick = React.useCallback(() => {
        // return animation on clear click
        setIsDisabledButtonAnimation(false);
        clearValue();
    }, [clearValue]);

    const renderCounterComponent = () => {
        if (!hasCounter) {
            return null;
        }
        const count = value.length;
        const counterComponent = <SelectCounter count={count} size={size} disabled={disabled} />;
        return renderCounter
            ? renderCounter(counterComponent, {count, size, disabled})
            : counterComponent;
    };

    const renderClearIcon = (args: SelectRenderClearArgs) => {
        const valueIsEmpty = value.length === 0;
        if (!hasClear || valueIsEmpty || disabled) {
            return null;
        }
        return (
            <SelectClear
                size={size}
                onClick={handleOnClearIconClick}
                onMouseEnter={disableButtonAnimation}
                onMouseLeave={enableButtonAnimation}
                renderIcon={args.renderIcon}
            />
        );
    };

    const triggerProps: SelectRenderTriggerProps = {
        ...filterDOMProps(props, {labelable: true}),
        id: selectId,
        role: 'combobox',
        'aria-controls': open ? popupId : undefined,
        'aria-haspopup': 'listbox',
        'aria-expanded': open,
        'aria-invalid': isErrorVisible || undefined,
        'aria-activedescendant':
            activeIndex === undefined ? undefined : `${popupId}-item-${activeIndex}`,
        onClick: handleControlClick,
        onKeyDown,
        disabled,
    };

    const {t} = i18n.useTranslation();

    if (renderControl) {
        return renderControl(
            {
                onClear: clearValue,
                renderClear: renderClearIcon,
                renderCounter: renderCounterComponent,
                ref,
                open,
                disabled,
                triggerProps,
            },
            {value},
        );
    }

    return (
        <React.Fragment>
            <div className={selectControlBlock(controlMods)} role="group">
                <button
                    ref={ref}
                    className={selectControlButtonBlock(buttonMods, className)}
                    type="button"
                    data-qa={qa}
                    title={title}
                    tabIndex={0}
                    {...triggerProps}
                >
                    {label && <span className={selectControlBlock('label')}>{label}</span>}
                    {showPlaceholder && (
                        <span className={selectControlBlock('placeholder')}>{placeholder}</span>
                    )}
                    {showOptionsText && (
                        <span className={selectControlBlock('option-text')}>
                            {selectedOptionsContent}
                        </span>
                    )}
                </button>
                {renderCounterComponent()}
                {renderClearIcon({})}

                {errorMessage && (
                    <Popover
                        placement={direction === 'rtl' ? ['left', 'bottom'] : ['right', 'bottom']}
                        hasArrow
                        className={selectControlBlock('error-popover')}
                        content={
                            <Alert
                                className={selectControlBlock('error-popover-content')}
                                theme="clear"
                                message={<div role="presentation">{errorMessage}</div>}
                            />
                        }
                    >
                        <button
                            aria-label={t('label_show-error-info')}
                            type={'button'}
                            className={selectControlBlock('error-icon')}
                        >
                            <Icon data={TriangleExclamation} size={size === 's' ? 12 : 16} />
                        </button>
                    </Popover>
                )}

                <Icon
                    className={selectControlBlock('chevron-icon', {disabled})}
                    data={ChevronDown}
                    aria-hidden="true"
                />
            </div>
        </React.Fragment>
    );
});

SelectControl.displayName = 'SelectControl';
"]}
